{
  "title": "Discussion about living and working abroad in Central Europe",
  "topics": [
    {
      "id": "living-abroad",
      "title": "Who lives or has lived abroad",
      "claims": [
        {
          "text": "P1 asked if anyone lives in Bratislava or elsewhere in Slovakia and who has moved abroad",
          "evidence": [1]
        },
        {
          "text": "P2 mentioned two acquaintances abroad: @AndriiRaccoon in Austria and walternet134 in Poland",
          "evidence": [3]
        },
        {
          "text": "P3 said they have at least two acquaintances in Austria",
          "evidence": [12]
        },
        {
          "text": "P3 reported one acquaintance recently arrived in Austria and another has been there for several years",
          "evidence": [13]
        },
        {
          "text": "P3 stated they have been living in Austria since 17.11.2025",
          "evidence": [49]
        },
        {
          "text": "P1 said they have been in Slovakia for almost a year",
          "evidence": [43]
        }
      ]
    },
    {
      "id": "job-search",
      "title": "Finding a job abroad",
      "claims": [
        {
          "text": "P1 asked how P3 found a job in Austria and whether it was difficult",
          "evidence": [16]
        },
        {
          "text": "P3 said it was hard but they managed within two months",
          "evidence": [17]
        },
        {
          "text": "P3 recommended searching on LinkedIn",
          "evidence": [18]
        },
        {
          "text": "P3 said they sent about 100 applications and got only three interviews",
          "evidence": [21]
        },
        {
          "text": "P3 noted that most job postings require local language proficiency",
          "evidence": [26]
        },
        {
          "text": "P3 mentioned they sometimes applied to positions without language requirements and were still considered",
          "evidence": [29]
        },
        {
          "text": "P3 stated they accepted a low salary because they needed a job quickly",
          "evidence": [37]
        },
        {
          "text": "P3 said they needed to find a job by 04.03 and therefore accepted the offer",
          "evidence": [39]
        },
        {
          "text": "P3 indicated they started working on 02.03",
          "evidence": [41]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language expectations for jobs",
      "claims": [
        {
          "text": "P1 asked which language is spoken in Austria; P3 replied German but they communicate in English with them",
          "evidence": [14,15]
        },
        {
          "text": "P3 said most job ads ask for B2 level German, sometimes B1, and a certificate is rarely required",
          "evidence": [46]
        },
        {
          "text": "P3 is learning the local language because of daily life difficulties",
          "evidence": [47]
        },
        {
          "text": "P1 noted that language barrier makes English feel awkward outside of work",
          "evidence": [51]
        },
        {
          "text": "P1 feels not very confident in English beyond work contexts",
          "evidence": [52]
        }
      ]
    },
    {
      "id": "salary",
      "title": "Salary expectations",
      "claims": [
        {
          "text": "P1 asked about approximate salary for a junior position",
          "evidence": [34]
        },
        {
          "text": "P3 believes salaries in Europe are higher than in Ukraine but few notice",
          "evidence": [35]
        },
        {
          "text": "P3 said their salary was higher than a minimum wage but still low compared to other jobs",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "networking-and-learning",
      "title": "Improving language and networking",
      "claims": [
        {
          "text": "P1 suggested joining Discord channels to improve spoken English",
          "evidence": [56,57]
        },
        {
          "text": "P3 mentioned attending international events (e.g., wawtech.io summer) as a way to use English",
          "evidence": [59]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "P1 asked if P3 plans to stay in Austria long term",
      "evidence": [58]
    }
  ]
}
